<template><div v-if="order" class="space-y-4 p-4"><h1 class="text-xl font-bold text-slate-800">Order {{ order.id.slice(0,8) }}</h1><div class="m-card"><p class="font-semibold">{{ order.status }}</p><p class="text-xs text-slate-400">{{ money(order.total_minor,order.currency) }}</p></div><form class="m-card space-y-3" @submit.prevent="schedule"><input v-model="form.carrier" class="m-input" placeholder="Carrier"/><input v-model="form.tracking_number" class="m-input" placeholder="Tracking number"/><button class="m-btn-primary">Schedule delivery</button></form><div v-for="item in deliveries" :key="item.id" class="m-card"><p class="font-semibold">{{ item.status }}</p><p class="text-xs text-slate-400">{{ item.carrier }} {{ item.tracking_number }}</p><button v-if="next[item.status]" class="mt-2 text-xs font-semibold text-blue-600" @click="advance(item.id,next[item.status])">Mark {{ next[item.status] }}</button></div><NuxtLink :to="`/messages/${order.id}`" class="m-card block text-center text-sm font-semibold">Open messages</NuxtLink><p v-if="error" class="text-xs text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">definePageMeta({middleware:['auth']});const route=useRoute();const {apiFetch}=useApi();const api=useCommerce();const order=ref<any>();const deliveries=ref<any[]>([]);const error=ref('');const form=reactive({carrier:'',tracking_number:''});const next:Record<string,string>={scheduled:'shipped',shipped:'in_transit',in_transit:'delivered'};const money=(v:number,c:string)=>new Intl.NumberFormat(undefined,{style:'currency',currency:c}).format(v/100);async function load(){order.value=await api.getOrder(String(route.params.id));deliveries.value=(await api.listDeliveries(String(route.params.id))).items}async function schedule(){await apiFetch(`/commerce/orders/${route.params.id}/deliveries`,{method:'POST',body:form});await load()}async function advance(id:string,status:string){await apiFetch(`/commerce/deliveries/${id}/status`,{method:'PATCH',body:{status}});await load()}onMounted(()=>load().catch((e:any)=>error.value=e?.data?.detail||e?.message))</script>
